(async () => {
  const { existsSync, readFileSync } = await import('node:fs');
  const imagePath = process.env.IMAGE_PATH;
  if (!imagePath) throw new Error('IMAGE_PATH env var not set');
  if (!existsSync(imagePath)) throw new Error(`Image file not found: ${imagePath}`);
  globalThis.imageBytes = readFileSync(imagePath);
})();

(async () => {
  const { PDFDocument, StandardFonts } = await import('pdf-lib');
  const pdfDoc = await PDFDocument.create();
  const pngImage = await pdfDoc.embedPng(globalThis.imageBytes);
  const helvetica = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const margin = 50;

  // ---- Page 1: title + image ----
  const page1 = pdfDoc.addPage();
  const { width, height } = page1.getSize();
  const title = 'Sample Image';
  const titleSize = 24;
  const titleWidth = helveticaBold.widthOfTextAtSize(title, titleSize);
  page1.drawText(title, {
    x: (width - titleWidth) / 2,
    y: height - margin - titleSize,
    size: titleSize,
    font: helveticaBold,
  });
  const imgMaxW = width - 2 * margin;
  const imgMaxH = height - 3 * margin - titleSize;
  const scale = Math.min(imgMaxW / pngImage.width, imgMaxH / pngImage.height);
  const imgW = pngImage.width * scale;
  const imgH = pngImage.height * scale;
  page1.drawImage(pngImage, {
    x: (width - imgW) / 2,
    y: margin,
    width: imgW,
    height: imgH,
  });

  // ---- Pages 2+: markdown content ----
  const md = `# Sample Heading
## Subheading
Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed non risus. Suspendisse lectus tortor, dignissim sit amet, adipiscing nec, ultricies sed, dolor. Cras elementum ultrices diam. Maecenas ligula massa, varius a, semper congue, euismod non, mi.

- Item one
- Item two
- Item three

Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque habitant morbi tristique senectus et netus et malesuada fames ac turpis egestas.`.repeat(3);
  const bodySize = 12;
  const headingSize = bodySize * 2;
  let curPage = pdfDoc.addPage();
  let { width: cw, height: ch } = curPage.getSize();
  const maxW = cw - 2 * margin;
  let cursorY = ch - margin;
  const textX = margin;

  function newPage() {
    curPage = pdfDoc.addPage();
    ({ width: cw, height: ch } = curPage.getSize());
    cursorY = ch - margin;
  }

  function drawWrapped(txt, size, font) {
    const words = txt.split(' ');
    let line = '';
    for (const w of words) {
      const test = line ? line + ' ' + w : w;
      const wWidth = font.widthOfTextAtSize(test, size);
      if (wWidth > maxW) {
        curPage.drawText(line, { x: textX, y: cursorY, size, font });
        cursorY -= size + 4;
        if (cursorY < margin) newPage();
        line = w;
      } else {
        line = test;
      }
    }
    if (line) {
      curPage.drawText(line, { x: textX, y: cursorY, size, font });
      cursorY -= size + 4;
      if (cursorY < margin) newPage();
    }
  }

  for (const raw of md.split('\n')) {
    if (raw.startsWith('# ')) {
      drawWrapped(raw.slice(2), headingSize, helveticaBold);
    } else if (raw.startsWith('## ')) {
      drawWrapped(raw.slice(3), headingSize, helveticaBold);
    } else if (raw.startsWith('- ')) {
      drawWrapped('• ' + raw.slice(2), bodySize, helvetica);
    } else if (raw.trim() === '') {
      cursorY -= bodySize;
      if (cursorY < margin) newPage();
    } else {
      drawWrapped(raw, bodySize, helvetica);
    }
  }

  // Ensure at least three pages total
  while (pdfDoc.getPageCount() < 3) pdfDoc.addPage();

  const pdfBytes = await pdfDoc.save();
  globalThis.pdfBytes = pdfBytes;
})();

(async () => {
  if (!globalThis.pdfBytes) throw new Error('No PDF bytes available');
  const base64 = Buffer.from(globalThis.pdfBytes).toString('base64');
  console.log(JSON.stringify({ pdf_base64: base64 }));
})();
